Question: How can you create your own EventEmitter in Node.js?

Answer: const EventEmitter = require('events');
    const emitter = new EventEmitter();
    emitter.on('event', () => console.log('An event occurred!'));
    emitter.emit('event');

answer:
const EventEmitter = require('events');
    const emitter = new EventEmitter();
    emitter.on('event', () => console.log('An event occurred!'));
    emitter.emit('event');
